(function(){
  'use strict';const G=window.G;if(!G)return;
  const defaults={enabled:true,voice:'Aoede',models:'gemini-3.8-flash-lite-tts,gemini-3.8-flash-tts,gemini-3.1-flash-tts-preview',allowPro:false};
  let config={...defaults};try{config={...defaults,...JSON.parse(localStorage.getItem('saras_voice')||'{}')};}catch(e){}
  let sequence=0,source=null,context=null,cooldown=0,controller=null;const clips=new Map();
  function stop(){sequence++;controller?.abort();controller=null;try{source?.stop();}catch(e){}source=null;}
  G.stopNaturalSpeech=stop;
  // PCM L16 generated by Gemini is mono signed 16-bit little-endian audio.
  function decode(data,mime){const raw=atob(data),rate=Number((mime.match(/rate=(\d+)/)||[])[1]||24000);if(!/audio\/(L16|pcm)/i.test(mime))throw Error('Unsupported audio format');const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const view=new DataView(bytes.buffer);const buffer=context.createBuffer(1,Math.floor(raw.length/2),rate);const floats=buffer.getChannelData(0);for(let i=0;i<floats.length;i++)floats[i]=view.getInt16(i*2,true)/32768;return buffer;}
  G.naturalSpeech=async function(text){
    stop();const id=sequence;
    if(!config.enabled||!navigator.onLine||G.S.mode==='offline'||!G.S.keys.gemini||Date.now()<cooldown)return false;
    const key=config.voice+'|'+config.models+'|'+text;
    try{
      const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return false;context=context||new Audio();await context.resume();
      let buffer=clips.get(key);
      if(!buffer){controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),25000);let result;
        try{const r=await fetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({key:G.S.keys.gemini,text:String(text).slice(0,650),voice:config.voice,models:config.models.split(',').map(x=>x.trim()).filter(Boolean),allowPro:config.allowPro})});if(!r.ok){cooldown=Date.now()+120000;throw Error('Voice provider unavailable');}result=await r.json();}finally{clearTimeout(timeout);}
        if(id!==sequence)return true;
        if(/wav|mpeg|ogg/i.test(result.mimeType||'')){const raw=atob(result.audio);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));buffer=await context.decodeAudioData(bytes.buffer);}else buffer=decode(result.audio,result.mimeType||'audio/L16;rate=24000');clips.set(key,buffer);if(clips.size>16)clips.delete(clips.keys().next().value);G.voiceModel=result.model;
      }
      if(id!==sequence)return true;
      source=context.createBufferSource();source.buffer=buffer;source.connect(context.destination);
      await new Promise(resolve=>{source.onended=resolve;source.start();});return true;
    }catch(e){return id!==sequence;} // Stale requests must not speak a device fallback.
  };
  G.hooks.ready.push(()=>{
    const settings=G.$('settings').querySelector('.card');if(!settings)return;
    const block=document.createElement('fieldset');block.style.cssText='margin:16px 0;border:1px solid #527462;border-radius:12px;padding:12px';
    block.innerHTML='<legend>Natural Gemini voice</legend><label><input type="checkbox" id="nvEnabled"> Natural voice + automatic fallback</label><p><small>Uses your Gemini key above. Voice quota is separate from text AI. Free access depends on your account; this does not bypass limits. Turn off for device voice.</small></p><label>Voice <select id="nvVoice"><option>Aoede</option><option>Kore</option><option>Leda</option><option>Zephyr</option><option>Puck</option></select></label><label style="display:block;margin-top:10px">TTS model routing order<input id="nvModels" style="width:95%" aria-label="TTS model routing order"></label><label><input type="checkbox" id="nvPro"> Allow Pro fallback (may require billing)</label><p><button class="btn" id="nvSave" type="button">Save voice</button> <button class="btn" id="nvTest" type="button">Test voice</button></p><small id="nvStatus">Device voice works when natural voice is unavailable.</small>';
    settings.appendChild(block);block.querySelector('#nvEnabled').checked=config.enabled;block.querySelector('#nvVoice').value=config.voice;block.querySelector('#nvModels').value=config.models;block.querySelector('#nvPro').checked=config.allowPro;
    const save=()=>{config={enabled:block.querySelector('#nvEnabled').checked,voice:block.querySelector('#nvVoice').value,models:block.querySelector('#nvModels').value.slice(0,250),allowPro:block.querySelector('#nvPro').checked};try{localStorage.setItem('saras_voice',JSON.stringify(config));}catch(e){}cooldown=0;};
    block.querySelector('#nvSave').onclick=()=>{save();block.querySelector('#nvStatus').textContent='Voice settings saved.';};
    block.querySelector('#nvTest').onclick=async()=>{save();const key=G.$('kGem').value.trim();if(key)G.S.keys.gemini=key;const status=block.querySelector('#nvStatus');status.textContent='Generating natural voice…';const ok=await G.naturalSpeech('Salam! Main Saras hoon. Chalo, apne shehar ka safar shuru karte hain.');status.textContent=ok?'Natural voice: '+(G.voiceModel||'played'):'Natural voice unavailable. Save a valid Gemini key, check quota, or use device voice.';};
    G.$('bSnd').addEventListener('click',stop);
    document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
  });
})();
